function solve(a, b, c){
  if(a===0) return {error:'a must not be 0'};
  var D = b*b - 4*a*c;
  if(D>=0){
    var sq=Math.sqrt(D);
    return { type:'real', D:D, roots:[ (-b+sq)/(2*a), (-b-sq)/(2*a) ] };
  } else {
    var sqi=Math.sqrt(-D)/(2*a);
    var r=-b/(2*a);
    return { type:'complex', D:D, roots:[ {re:r, im:sqi}, {re:r, im:-sqi} ] };
  }
}
var EXPORTS={ solve:solve };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.QuadraticForgePure = EXPORTS; }
